import React, { useState } from 'react';
import { deleteCamera, updateCamera } from '../services/api';
import { useApp } from '../context/AppContext';

const detColors = {
  Normal: '#22c55e', Phone: '#60a5fa', Medical_Mask: '#34d399',
  Fire: '#ef4444',  Smoke: '#94a3b8', Gun: '#f87171',
  Knife: '#facc15', Falling: '#a78bfa', Violence: '#a855f7',
  Theft_Mask: '#fbbf24'
};

const threatBorder = {
  Fire: '#7f1d1d', Violence: '#7f1d3f',
  Gun:  '#7f1d1d', Knife: '#7f6d00'
};

export default function CameraCard({ camera, showControls = false }) {
  const { refreshCameras } = useApp();
  const [deleting,  setDeleting]  = useState(false);
  const [toggling,  setToggling]  = useState(false);
  const [showMenu,  setShowMenu]  = useState(false);

  const isOnline   = camera.status === 'online';
  const lastClass  = camera.last_class || 'Normal';
  const lastConf   = camera.last_conf  || 0.92;
  const detColor   = detColors[lastClass] || '#22c55e';
  const borderCol  = isOnline ? (threatBorder[lastClass] || '#1e2d47') : '#1e2d47';

  const handleDelete = async () => {
    if (!window.confirm(`Delete ${camera.name}?`)) return;
    setDeleting(true);
    try {
      await deleteCamera(camera.id);
      await refreshCameras();
    } catch (err) {
      alert('Failed to delete camera');
    } finally {
      setDeleting(false);
    }
  };

  const handleToggle = async () => {
    setToggling(true);
    try {
      await updateCamera(camera.id, {
        status: isOnline ? 'offline' : 'online'
      });
      await refreshCameras();
    } catch (err) {
      alert('Failed to update camera');
    } finally {
      setToggling(false);
      setShowMenu(false);
    }
  };

  return (
    <div style={{
      background: '#151d2e',
      border: `1px solid ${borderCol}`,
      borderRadius: 8, overflow: 'hidden',
      opacity: deleting ? 0.5 : 1,
      position: 'relative',
      transition: 'opacity .3s'
    }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '5px 8px', background: '#1a2340' }}>
        <span style={{ fontSize: 10, fontWeight: 600, color: '#e2e8f0' }}>{camera.name}</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {isOnline ? (
            <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9, color: '#22c55e' }}>
              <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#22c55e', display: 'inline-block', animation: 'livePulse 1.5s infinite' }} />
              Live
              <style>{`@keyframes livePulse{0%,100%{opacity:1}50%{opacity:.3}}`}</style>
            </span>
          ) : (
            <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 9, color: '#64748b' }}>
              <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#64748b', display: 'inline-block' }} />
              Offline
            </span>
          )}
        </div>
      </div>


      {/* Feed */}
<div style={{
  height: 110, background: '#080f1a',
  position: 'relative',
  display: 'flex', alignItems: 'center', justifyContent: 'center',
  overflow: 'hidden'
}}>
  {isOnline ? (
    <>
      <img
        src={`http://localhost:8000/cameras/${camera.id}/stream`}
        alt={camera.name}
        style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
        onError={(e) => { e.target.style.display = 'none'; }}
      />
      <div style={{
        position: 'absolute', top: '20%', left: '15%',
        border: `2px solid ${detColor}`, borderRadius: 4,
        padding: '2px 6px', fontSize: 9, fontWeight: 700,
        color: detColor, background: `${detColor}22`
      }}>
        {lastClass} {lastConf}
      </div>
    </>
  ) : (
    <span style={{ fontSize: 11, color: '#64748b' }}>[ Offline ]</span>
  )}
</div>

      {/* Footer */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '4px 8px', background: '#1a2340', position: 'relative' }}>
        <span style={{ fontSize: 12, color: '#64748b' }}>📷</span>
        <span style={{ fontSize: 12, color: '#64748b' }}>⛶</span>

        {/* Menu button */}
        <span
          style={{ fontSize: 14, color: '#64748b', cursor: 'pointer', padding: '0 4px' }}
          onClick={() => setShowMenu(!showMenu)}
        >⋯</span>

        <div style={{ display: 'flex', gap: 1, alignItems: 'flex-end' }}>
          {[4, 6, 8, 10].map((h, i) => (
            <span key={i} style={{ width: 2, height: h, background: isOnline ? '#22c55e' : '#253550', borderRadius: 1, display: 'block' }} />
          ))}
        </div>

        {/* Dropdown menu */}
        {showMenu && (
          <div style={{
            position: 'absolute', bottom: '100%', right: 0,
            background: '#1a2340', border: '1px solid #253550',
            borderRadius: 6, overflow: 'hidden', zIndex: 100,
            minWidth: 140, boxShadow: '0 4px 12px rgba(0,0,0,.5)'
          }}>
            <div
              onClick={handleToggle}
              style={{ padding: '8px 12px', fontSize: 11, color: isOnline ? '#fbbf24' : '#4ade80', cursor: toggling ? 'not-allowed' : 'pointer', borderBottom: '1px solid #253550' }}
            >
              {toggling ? 'Updating...' : isOnline ? '⏸ Set Offline' : '▶ Set Online'}
            </div>
            <div
              onClick={handleDelete}
              style={{ padding: '8px 12px', fontSize: 11, color: '#f87171', cursor: deleting ? 'not-allowed' : 'pointer' }}
            >
              🗑 Delete Camera
            </div>
          </div>
        )}
      </div>

      {/* Detections badge */}
      {camera.detections > 0 && (
        <div style={{
          position: 'absolute', top: 30, right: 6,
          background: '#1e3a5f', color: '#60a5fa',
          fontSize: 9, fontWeight: 700,
          padding: '2px 5px', borderRadius: 4
        }}>
          {camera.detections} det
        </div>
      )}
    </div>
  );
}
